    func testASCIIUnsupportedTextAndUnsupportedKeyTypeNothing() async throws {
        let ascii = BackendDeckToolsMachinesPortDevices(); await ascii.detail("text", .string("ascii")); let accented = try await BackendDeckToolsMachinesPortDeviceCall(ascii, "devices.type", args(["text": .string("café")])), asciiCalls = await ascii.names(); XCTAssertTrue(accented.structuredContent?["error"].string?.contains("plain ASCII") == true); BackendDeckToolsMachinesPortEqual(asciiCalls, ["open"])
